"""Exposed diagnosis only; fresh hand-authored scenario pairs, never training/release."""
import json,hashlib
from pathlib import Path
P=Path(__file__).resolve().parent
rows=[]
def pair(family,scenario,a,b,ea,eb,rule='fact'):
    rows.append(dict(id=f'{family}-{scenario}',family=family,variants=[dict(prompt=a,expected=ea),dict(prompt=b,expected=eb)],rubric=rule))
pair('entity','luggage','Leela checked a striped suitcase. Harish checked a silver suitcase. Who checked the silver suitcase?','Harish checked a striped suitcase. Leela checked a silver suitcase. Who checked the silver suitcase?','Harish','Leela')
